    if (ni_cov_mmio_sendTLB < 20) begin cov_fail++; $display("[COV] NewIFU.mmio_sendTLB < 20"); end
    $display("[COV] NewIFU.mmio_tlbResp = %0d", ni_cov_mmio_tlbResp);
    if (ni_cov_mmio_tlbResp < 20) begin cov_fail++; $display("[COV] NewIFU.mmio_tlbResp < 20"); end
    $display("[COV] NewIFU.mmio_sendPMP = %0d", ni_cov_mmio_sendPMP);
    if (ni_cov_mmio_sendPMP < 20) begin cov_fail++; $display("[COV] NewIFU.mmio_sendPMP < 20"); end
    $display("[COV] NewIFU.mmio_pmpResp = %0d", ni_cov_mmio_pmpResp);
    if (ni_cov_mmio_pmpResp < 20) begin cov_fail++; $display("[COV] NewIFU.mmio_pmpResp < 20"); end
    $display("[COV] NewIFU.mmio_resendReq = %0d", ni_cov_mmio_resendReq);
    if (ni_cov_mmio_resendReq < 20) begin cov_fail++; $display("[COV] NewIFU.mmio_resendReq < 20"); end
    $display("[COV] NewIFU.mmio_waitResendResp = %0d", ni_cov_mmio_waitResendResp);
    if (ni_cov_mmio_waitResendResp < 20) begin cov_fail++; $display("[COV] NewIFU.mmio_waitResendResp < 20"); end
    $display("[COV] NewIFU.mmio_waitCommit = %0d", ni_cov_mmio_waitCommit);
    if (ni_cov_mmio_waitCommit < 20) begin cov_fail++; $display("[COV] NewIFU.mmio_waitCommit < 20"); end
    $display("[COV] NewIFU.mmio_commited = %0d", ni_cov_mmio_commited);
    if (ni_cov_mmio_commited < 20) begin cov_fail++; $display("[COV] NewIFU.mmio_commited < 20"); end
    $display("checks=%0d errors=%0d cov_fail=%0d", checks, errors, cov_fail);
    if (errors == 0 && cov_fail == 0 && checks > 0) $display("TEST PASSED");
    else $display("TEST FAILED");
    $finish;
  end
endmodule
